import sys

def deposit():
    while True:
        amount = input("Enter deposit amount: ")
        if not amount.isdigit():
            print("Please enter only digits.")
            continue
        value = int(amount)
        if value <= 0:
            print("Amount must be greater than zero.")
            continue
        return value

def main():
    total = deposit()
    print(f"Deposit accepted: {total}")

if __name__ == "__main__":
